ll mod_inverse(ll a, ll mod) {
    ll m0 = mod, x0 = 0, x1 = 1;
    if (mod == 1) return 0;
    while (a > 1) {
        ll q = a / mod;
        ll t = mod;
        mod = a % mod;
        a = t;
        t = x0;
        x0 = x1 - q * x0;
        x1 = t;
    }
    if (x1 < 0) x1 += m0;
    return x1;
}

