// Find primitive root modulo prime p
int find_primitive_root(int p) {
    if (p == 2) return 1;
    // Factorize p-1
    vector<int> factors;
    int n = p - 1;
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            factors.push_back(i);
            while (n % i == 0) {
                n /= i;
            }
        }
    }
    if (n > 1) {
        factors.push_back(n);
    }
    // Try candidates
    for (int g = 2; g < p; g++) {
        bool is_root = true;
        for (int factor : factors) {
            if (mod_pow(g, (p - 1) / factor, p) == 1) {
                is_root = false;
                break;
            }
        }
        if (is_root) {
            return g;
        }
    }
    return -1; // Should not happen for prime p
}

