// Find primitive root of prime p
ll find_primitive_root(ll p) {
    if (p == 2) return 1;

    // Factorize p-1
    vector<ll> factors;
    ll n = p - 1;
    for (ll i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            factors.push_back(i);
            while (n % i == 0) {
                n /= i;
            }
        }
    }
    if (n > 1) {
        factors.push_back(n);
    }

    // Try candidates
    for (ll g = 2; g < p; g++) {
        bool is_primitive = true;
        for (ll f : factors) {
            if (mod_pow(g, (p - 1) / f, p) == 1) {
                is_primitive = false;
                break;
            }
        }
        if (is_primitive) {
            return g;
        }
    }
    return -1; // Should not happen for prime p
}

// Baby-step giant-step to solve g^x = h mod p
