    // So we compute g^(-m) mod p
    ll g_inv_m = mod_pow(mod_pow(g, m, p), p - 2, p); // g^(-m) mod p

    ll giant = h % p;
    for (ll i = 1; i <= m; i++) {
        // Check if giant is in baby_steps
        auto it = lower_bound(baby_steps.begin(), baby_steps.end(), make_pair(giant, -1));
